-- Ảnh thật có giấy phép mở cho dữ liệu mẫu Mù Cang Chải / Tú Lệ (MySQL).
-- Sinh tự động từ danh mục ảnh đã kiểm tra bằng mắt; xem docs/bao-cao-anh-that.md.
-- Chạy lại nhiều lần vẫn an toàn: media_asset upsert theo checksum, liên kết được xóa và tạo lại.
-- Chỉ đụng tới ảnh picsum (ảnh tạm) và ảnh external/* do chính script này tạo.
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Ảnh

-- 2. Gỡ liên kết cũ (ảnh picsum + ảnh external do script này tạo)
DELETE pm FROM place_media pm JOIN media_asset m ON m.id = pm.media_id WHERE m.public_url LIKE 'https://picsum.photos/%' OR m.storage_key LIKE 'external/%';
DELETE dm FROM dish_media dm JOIN media_asset m ON m.id = dm.media_id WHERE m.public_url LIKE 'https://picsum.photos/%' OR m.storage_key LIKE 'external/%';
DELETE rm FROM room_type_media rm JOIN media_asset m ON m.id = rm.media_id WHERE m.public_url LIKE 'https://picsum.photos/%' OR m.storage_key LIKE 'external/%';

-- 3. Ảnh địa điểm (COVER + GALLERY). Địa điểm có danh sách rỗng = chưa có ảnh đúng nơi đó.

-- 4. Ảnh món ăn

-- 5. Ảnh loại phòng (homestay mẫu: ảnh khu vực / ảnh minh họa, ghi rõ trong chú thích)

-- 6. Ảnh bìa lễ hội
UPDATE festival SET cover_image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Terraces_in_Che_Cu_Nha_commune%2C_Mu_Cang_Chai_%28Unsplash%29.jpg/1920px-Terraces_in_Che_Cu_Nha_commune%2C_Mu_Cang_Chai_%28Unsplash%29.jpg' WHERE slug = 'le-hoi-mua-vang-mu-cang-chai';
UPDATE festival SET cover_image_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Hmong_women_with_traditional_costume.jpg/1920px-Hmong_women_with_traditional_costume.jpg' WHERE slug = 'tet-nguoi-mong';
UPDATE festival SET cover_image_url = 'https://upload.wikimedia.org/wikipedia/commons/5/55/Nh%E1%BA%A3y_d%C3%B9_l%C6%B0%E1%BB%A3n_t%E1%BB%AB_%C4%91%C3%A8o_Khau_Ph%E1%BA%A1_ng%E1%BA%AFm_b%E1%BA%A3n_L%C3%ACm_m%C3%B4ng.jpg' WHERE slug = 'le-hoi-du-luon-khau-pha';

-- 7. Xóa ảnh picsum không còn ai dùng
DELETE FROM media_asset WHERE public_url LIKE 'https://picsum.photos/%' AND id NOT IN (SELECT media_id FROM place_media) AND id NOT IN (SELECT media_id FROM dish_media) AND id NOT IN (SELECT media_id FROM room_type_media);
UPDATE festival SET cover_image_url = NULL WHERE cover_image_url LIKE 'https://picsum.photos/%';

COMMIT;
